// Classification pipeline shared by the backend and the extension's direct mode:
// normalise request -> prompt -> model -> validate; one retry; then heuristic fallback.
import { classifyHeuristically } from './heuristic.js';
import { prepareModelInput } from './prompt.js';
import { normalizeClassifyRequest } from './request.js';
import { normalizeClassification } from './validate.js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function errorMessage(error) {
  return String(error?.message ?? error ?? 'Erreur inconnue').slice(0, 300);
}

/**
 * @param {object} rawRequest {tabs, existingGroups, language, maxGroups}
 * @param {{generate: (input: ReturnType<typeof prepareModelInput>) => Promise<string>,
 *          retries?: number, retryDelayMs?: number, fallback?: boolean,
 *          onError?: (error: unknown, attempt: number) => void}} options
 * @returns {Promise<{groups: object[], ungrouped: number[], source: 'gemini'|'heuristic', attempts: number, error?: string}>}
 */
export async function runClassification(rawRequest, { generate, retries = 1, retryDelayMs = 300, fallback = true, onError } = {}) {
  const request = normalizeClassifyRequest(rawRequest); // throws RequestError (400) on bad input
  const input = prepareModelInput(request);
  let lastError = null;
  let attempts = 0;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    attempts = attempt + 1;
    try {
      const text = await generate(input);
      return { ...normalizeClassification(text, input.ctx), source: 'gemini', attempts };
    } catch (error) {
      lastError = error;
      onError?.(error, attempt);
      if (error?.retryable === false) break; // bad key, permission denied… retrying is pointless
      if (attempt < retries) await sleep(retryDelayMs);
    }
  }

  if (!fallback) throw lastError;
  return { ...classifyHeuristically(request), source: 'heuristic', attempts, error: errorMessage(lastError) };
}
